insert into public.site_settings(key,value,is_public)
values
  ('jobs_page_copy', to_jsonb(E'ar:default || كل الفرص || محرك البحث || صنّف النتائج بدل قراءة مئات الإعلانات. ابدأ من دولتك ومستواك، ثم اقرأ ما يهمّك فقط.\nar:students || فرص الطلاب || وظائف أثناء الدراسة || دوام جزئي، تدريب مدفوع، وعمل حر لا يتعارض مع جدول المحاضرات. حدّد عدد ساعاتك المتاحة وسيُستبعد ما لا يناسبك.\nar:no-experience || ابدأ من الصفر || وظائف لا تشترط خبرة || هنا لا يوجد شرط سنوات سابقة. كل ما تحتاجه هو ساعة أو ساعتان يومياً للتعلم، والاستعداد لتقديم عملك الأول.\nar:remote || العمل عن بُعد || كل الوظائف عن بُعد || بدون تنقل، وبدون بطاقة إقامة في بلد آخر. لكن انتبه: كلمة Remote وحدها لا تعني أن دولتك مقبولة — ولهذا نوضح ذلك في كل بطاقة.\nen:remote || Remote jobs || Remote Jobs Worldwide || Find remote opportunities and check geographic eligibility, experience and application details before you apply.\nfr:remote || Télétravail || Emplois en télétravail || Trouvez des emplois à distance et vérifiez l’éligibilité géographique avant de postuler.\nen:default || Job search || Online & Remote Jobs || Explore jobs, compare eligibility and prepare a stronger application.\nfr:default || Recherche d’emploi || Emplois en ligne et à distance || Explorez les offres, comparez votre éligibilité et préparez une meilleure candidature.'::text), true),
  ('jobs_search_placeholder_copy', to_jsonb(E'ar || ابحث بكلمة أو مهارة\nen || Search by keyword or skill\nfr || Recherchez par mot-clé ou compétence'::text), true),
  ('jobs_no_results_copy', to_jsonb(E'ar || لا توجد فرص بهذه الشروط || جرّب توسيع أحد الفلاتر — مثلاً إزالة قيد الخبرة أو اختيار «الأهلية: غير واضحة».\nen || No jobs match these filters || Try widening one filter, such as removing the experience requirement.\nfr || Aucune offre ne correspond à ces critères || Élargissez un filtre, par exemple en retirant la contrainte d’expérience.'::text), true),
  ('jobs_profile_copy', to_jsonb(E'ar || ملفك || غيّر دولتك أو مستواك وشاهد كيف تتغير النتائج || يُحفظ ملفك في متصفحك فقط، ولا يُرسل إلى أي خادم.\nen || Your profile || Change your country or experience level to see how results change || Your profile is stored only in your browser and is not sent to a server.\nfr || Votre profil || Changez votre pays ou votre niveau pour voir comment les résultats évoluent || Votre profil est conservé uniquement dans votre navigateur et n’est envoyé à aucun serveur.'::text), true),
  ('jobs_match_copy', to_jsonb(E'ar || رتّبنا النتائج حسب ملفك المحفوظ. أعلى نتيجة {score} من 100. || مضبوطة على {country} || عدّل ملفك\nen || We ranked the results using your saved profile. Top result: {score}/100. || Tuned to {country} || Edit profile\nfr || Nous avons classé les résultats selon votre profil enregistré. Meilleur score : {score}/100. || Adapté à {country} || Modifier le profil'::text), true)
